\usepackage[english,indonesian]{babel}
\usepackage{ragged2e}
\usepackage{xcolor}
\usepackage{tcolorbox}      % Untuk kotak berwarna
\usepackage{geometry}       % Untuk mengatur margin cover
\usepackage{setspace}       % Untuk spasi

% ===== Warna (sesuai Springer LNCS) =====
