\hyphenation{op-tical net-works semi-conduc-tor}

\begin{document}

% ============================================================
% COVER PAGE ALA SPRINGER (HALAMAN TERPISAH)
% ============================================================
\begin{titlepage}
\thispagestyle{empty}
